INDUSTRY_ID = os.getenv("INDUSTRY_ID", "YOUR_INDUSTRY_ID")
SENSOR_ID = os.getenv("SENSOR_ID", "YOUR_SENSOR_ID")
SMART_METER_ID = os.getenv("SMART_METER_ID", "YOUR_SMART_METER_ID")

# Supply actual meter readings as [{"timestamp": "...", "usage": 123.4}, ...].
SMART_METER_READINGS = json.loads(os.getenv("SMART_METER_READINGS", "[]"))

# These thresholds configure local checks; the documented API has no alert-configuration endpoint.
ALERT_THRESHOLDS = {
    "meter_usage_kwh": float(os.getenv("ALERT_USAGE_KWH", "1000")),
    "real_time_demand": float(os.getenv("ALERT_DEMAND", "10000")),
}

today = date.today()
first_of_this_month = today.replace(day=1)
last_month_end = first_of_this_month - __import__("datetime").timedelta(days=1)
last_month_start = last_month_end.replace(day=1)

session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})


def get_json(path, params=None):
    response = session.get(f"{BASE_URL}{path}", params=params, timeout=30)
    response.raise_for_status()
    return response.json()


def send_json(method, path, payload):
    response = session.request(
        method, f"{BASE_URL}{path}", json=payload, timeout=30
    )
    response.raise_for_status()
    if response.content:
        try:
            return response.json()
        except ValueError:
            return response.text
    return None


