calibration = send_json(
    "PUT",
    "/sensors/calibration",
    {
        "sensor_id": SENSOR_ID,
        "calibration_settings": {
            "factor": float(os.getenv("CALIBRATION_FACTOR", "1.0")),
            "offset": float(os.getenv("CALIBRATION_OFFSET", "0.0")),
        },
    },
)

real_time = get_json("/real-time-data")
historical_demand = get_json(
    "/electricity-demand",
    params={
        "start_date": last_month_start.isoformat(),
        "end_date": last_month_end.isoformat(),
    },
)
forecast = get_json("/forecast-usage")

usage_details = {
    "industryEnergyUsage": industry_usage,
    "monthlyHistoricalDemand": historical_demand.get("data", []),
}
efficiency_assessment = send_json(
    "POST",
    "/equipment-efficiency-check",
    {
        "equipmentId": EQUIPMENT_ID,
        "industryId": INDUSTRY_ID,
        "usageDetails": json.dumps(usage_details),
    },
)

meter_upload = send_json(
    "POST",
    "/smart-meters/data",
    {
        "smart_meter_id": SMART_METER_ID,
        "data": SMART_METER_READINGS,
    },
)

# Evaluate the locally configured abnormal-usage thresholds.
alerts = []
for reading in SMART_METER_READINGS:
    usage = reading.get("usage")
    if isinstance(usage, (int, float)) and usage > ALERT_THRESHOLDS["meter_usage_kwh"]:
        alerts.append(
            {
                "type": "abnormal_meter_usage",
                "timestamp": reading.get("timestamp"),
                "usage": usage,
                "threshold": ALERT_THRESHOLDS["meter_usage_kwh"],
            }
        )

real_time_demand = real_time.get("data", {}).get("demand")
if (
    isinstance(real_time_demand, (int, float))
    and real_time_demand > ALERT_THRESHOLDS["real_time_demand"]
):
    alerts.append(
        {
            "type": "abnormal_real_time_demand",
            "timestamp": real_time.get("timestamp"),
            "demand": real_time_demand,
            "threshold": ALERT_THRESHOLDS["real_time_demand"],
        }
    )

demand_values = [
