    },
    "forecast": forecast,
    "real_time_data": real_time,
    "efficiency_assessment": efficiency_assessment,
    "sensor_calibration": calibration,
    "smart_meter_upload": meter_upload,
    "local_alert_thresholds": ALERT_THRESHOLDS,
    "alerts": alerts,
}

