import json
import os
from datetime import date
from urllib.parse import quote

import requests

BASE_URL = "https://api.socbench.example"
INDUSTRY_ID = os.environ.get("INDUSTRY_ID", "industrial")
SECTOR = os.environ.get("SECTOR", "industrial")
TIMEOUT = 30

session = requests.Session()
session.headers.update({"Accept": "application/json"})


def request_json(method, url, **kwargs):
    response = session.request(method, url, timeout=TIMEOUT, **kwargs)
    response.raise_for_status()
    if response.content:
        return response.json()
    return None


# Retrieve the existing plan and equipment data for review.
maintenance_schedule = request_json(
    "GET", f"{BASE_URL}/maintenance-schedule"
)
monitoring_data = request_json(
    "GET", f"{BASE_URL}/equipment-monitoring"
)

schedule_entries = maintenance_schedule or []
equipment_entries = (monitoring_data or {}).get("equipment", [])

# Check the retrieved schedule for issues to include in the requested review.
schedule_findings = []
seen_ids = set()

for entry in schedule_entries:
    entry_id = entry.get("id")
    if not entry_id:
        schedule_findings.append(
            {"issue": "Schedule entry is missing an ID", "entry": entry}
        )
    elif entry_id in seen_ids:
        schedule_findings.append(
            {"issue": "Duplicate schedule entry ID", "id": entry_id}
        )
    else:
        seen_ids.add(entry_id)

    scheduled_date = entry.get("date")
    if scheduled_date:
        try:
            date.fromisoformat(scheduled_date)
        except (TypeError, ValueError):
            schedule_findings.append(
                {
                    "issue": "Invalid schedule date",
                    "id": entry_id,
                    "date": scheduled_date,
                }
            )

    if entry.get("status") not in {"Pending", "Completed", "In Progress"}:
        schedule_findings.append(
            {
                "issue": "Missing or unexpected schedule status",
                "id": entry_id,
                "status": entry.get("status"),
            }
        )

# Submit each monitored item's current status and performance metrics as
# usage details for an equipment efficiency evaluation.
efficiency_evaluations = []
for equipment in equipment_entries:
    equipment_id = equipment.get("equipmentId")
    if not equipment_id:
        continue

    usage_details = {
        "currentStatus": equipment.get("status"),
        "performanceMetrics": equipment.get("performanceMetrics", {}),
    }
    evaluation = request_json(
        "POST",
        f"{BASE_URL}/equipment-efficiency-check",
        json={
            "equipmentId": equipment_id,
            "industryId": INDUSTRY_ID,
            "usageDetails": json.dumps(usage_details),
        },
    )
    efficiency_evaluations.append(
        {"equipmentId": equipment_id, "evaluation": evaluation}
    )

# Request recommendations that use the existing facility schedule and
# equipment evaluations to propose maintenance planning and improvements.
# The documented API has no dedicated maintenance-report feedback endpoint,
# so schedule findings and the requested review are included with this report.
recommendation_report = request_json(
    "POST",
    f"{BASE_URL}/recommendation-report",
    json={
        "sector": SECTOR,
        "parameters": {
            "industryId": INDUSTRY_ID,
            "maintenanceSchedule": schedule_entries,
            "scheduleAccuracyFindings": schedule_findings,
            "equipmentMonitoring": equipment_entries,
            "equipmentEfficiencyEvaluations": efficiency_evaluations,
            "requestedOutput": (
                "Propose a maintenance plan covering all facilities. Review "
                "the supplied maintenance schedule for accuracy and completeness, "
                "identify issues, and suggest improvements where applicable."
            ),
        },
    },
)

print(
    json.dumps(
        {
            "maintenanceSchedule": schedule_entries,
            "scheduleAccuracyFindings": schedule_findings,
            "equipmentEfficiencyEvaluations": efficiency_evaluations,
            "recommendationReportRequest": recommendation_report,
        },
        indent=2,
    )
)

