import json
import os
from datetime import date, timedelta

import requests

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30

site_payload = {
    "name": os.environ.get("SITE_NAME", "New mining site"),
    "location": os.environ.get("SITE_LOCATION", "Location to be specified"),
}

session = requests.Session()
session.headers.update({"Accept": "application/json"})


def get_json(path, **kwargs):
    response = session.get(f"{BASE_URL}{path}", timeout=TIMEOUT, **kwargs)
    response.raise_for_status()
    return response.json()


def post_json(path, payload):
    response = session.post(
        f"{BASE_URL}{path}",
        json=payload,
        timeout=TIMEOUT,
    )
    response.raise_for_status()
    return response.json() if response.content else {}


def as_list(data):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ("items", "results", "data", "equipment", "materials", "inventory"):
            value = data.get(key)
            if isinstance(value, list):
                return value
    return []


site = post_json("/sites/add", site_payload)
site_id = site.get("id") or site.get("site_id")
site_name = site.get("name") or site_payload["name"]

equipment_status = get_json("/equipment-status")
equipment = as_list(equipment_status)

operational_states = {"operational", "active", "running", "online"}
site_equipment = [
    item
    for item in equipment
    if (
        (site_id is not None and str(item.get("site_id")) == str(site_id))
        or (
            site_id is None
            and item.get("site_name") == site_name
        )
    )
    and str(item.get("status", item.get("operational_status", ""))).lower()
    in operational_states
]

maintenance_date = os.environ.get(
    "MAINTENANCE_DATE",
    (date.today() + timedelta(days=7)).isoformat(),
)
maintenance_results = []

for item in site_equipment:
    equipment_id = item.get("id") or item.get("equipment_id")
    if equipment_id is None:
        continue

    maintenance_payload = {
        "equipment_id": equipment_id,
        "site_id": site_id,
        "scheduled_date": maintenance_date,
        "status": "scheduled",
    }
    result = post_json("/equipment/maintenance-schedule", maintenance_payload)
    maintenance_results.append(
        {"equipment_id": equipment_id, "result": result}
    )

materials_response = get_json("/materials")
inventory_response = get_json("/inventory/status")
materials = as_list(materials_response)
inventory = as_list(inventory_response)

def belongs_to_site(record):
    record_site_id = record.get("site_id")
    record_site_name = record.get("site_name")
    location = str(record.get("location", ""))
    return (
        (site_id is not None and str(record_site_id) == str(site_id))
        or record_site_name == site_name
        or (not record_site_id and not record_site_name and site_name in location)
    )

site_inventory = [item for item in inventory if belongs_to_site(item)]
project_id = os.environ.get("PROJECT_ID")
project_materials = [
    item
    for item in site_inventory
    if project_id is None
    or str(item.get("project_id")) == project_id
]

obsolete_materials = [
    item
    for item in project_materials
    if str(item.get("status", item.get("availability_status", ""))).lower()
    in {"obsolete", "obsolete_material"}
]

report = {
    "site": site,
    "operational_equipment_status": site_equipment,
    "maintenance_schedules_submitted": maintenance_results,
    "project_materials_from_site_inventory": project_materials,
    "materials_catalog": materials,
    "obsolete_materials_identified": obsolete_materials,
    "regulatory_updates": {
        "status": "Unavailable: no regulatory updates endpoint is documented."
    },
    "obsolete_material_removal": {
        "status": "Not performed: no material removal endpoint is documented."
    },
}

print(json.dumps(report, indent=2, default=str))

import requests

BASE_URL = "https://api.socbench.example"
PRODUCT_CATEGORIES = []  # Optionally specify category names; otherwise use all returned categories.
REQUIRED_MATERIALS = []  # Supply items such as {"material_id": "123", "quantity": 50}.

session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})


def get_json(path, **kwargs):
    response = session.get(f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    return response.json()


def post_json(path, payload):
    response = session.post(f"{BASE_URL}{path}", json=payload, timeout=30)
    response.raise_for_status()
    return response.json()


def records_from(data, *keys):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in keys:
            value = data.get(key)
            if isinstance(value, list):
                return value
    return []


# Retrieve the updated classification categories and analyze trends for the
# requested categories, or for all categories when none were specified.
categories_result = get_json("/materials/categories")
categories = records_from(categories_result, "categories", "data", "results")

if not PRODUCT_CATEGORIES:
    PRODUCT_CATEGORIES = [
        item.get("name", item.get("category"))
        for item in categories
        if isinstance(item, dict) and item.get("name", item.get("category"))
    ]

trends = get_json(
    "/market-trends",
    params={"categories": PRODUCT_CATEGORIES},
)

# Review inventory before procurement and identify records explicitly marked
# as outdated. The documented API does not provide a material-removal endpoint.
inventory = get_json("/inventory/status")
inventory_items = records_from(inventory, "inventory", "items", "materials", "data")
outdated_materials = [
    item
    for item in inventory_items
    if isinstance(item, dict)
    and (
        item.get("outdated") is True
        or str(item.get("status", "")).lower() == "outdated"
    )
]

# Submit the required quantities together with the trend analysis as procurement
# context. Provide REQUIRED_MATERIALS with the materials and quantities needed.
procurement_result = None
compliance_results = []

if REQUIRED_MATERIALS:
    procurement_result = post_json(
        "/procurement/request",
        {
            "materials": REQUIRED_MATERIALS,
            "preferences": {
                "categories": PRODUCT_CATEGORIES,
                "market_trends": trends,
            },
        },
    )

    procurement_items = records_from(
        procurement_result, "materials", "items", "requested_materials", "data"
    )
    material_ids = {
        item.get("material_id", item.get("id"))
        for item in procurement_items
        if isinstance(item, dict)
        and item.get("material_id", item.get("id")) is not None
    }

    # Also check IDs supplied directly in the requested-material list.
    material_ids.update(
        item.get("material_id", item.get("id"))
        for item in REQUIRED_MATERIALS
        if isinstance(item, dict)
        and item.get("material_id", item.get("id")) is not None
    )

    for material_id in material_ids:
        compliance_results.append(
            {
                "material_id": material_id,
                "result": get_json(f"/materials/{material_id}/compliance"),
            }
        )

# No documented endpoint can remove outdated inventory materials. Keep the
# identified records for review rather than attempting an unsupported request.
result = {
    "categories": categories_result,
    "market_trends": trends,
    "inventory": inventory,
    "outdated_materials_identified": outdated_materials,
    "procurement": procurement_result,
    "compliance_results": compliance_results,
    "outdated_materials_removed": False,
}

