import os
import requests

API_BASE = "https://api.socbench.example"
API_TOKEN = os.getenv("SOCBENCH_API_TOKEN")

# Set these IDs to the materials and equipment involved. If MATERIAL_IDS is
# empty, the script checks all materials returned by GET /materials.
MATERIAL_IDS = []
EQUIPMENT_IDS = []

# Optional explicit property updates, keyed by material ID. Values should be
# fields accepted by PUT /materials/{id}, based on the applicable requirements.
PROPERTY_UPDATES = {}

session = requests.Session()
session.headers.update({"Accept": "application/json"})
if API_TOKEN:
    session.headers["Authorization"] = f"Bearer {API_TOKEN}"


def request_json(method, path, **kwargs):
    response = session.request(method, f"{API_BASE}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    if response.content:
        return response.json()
    return None


def items_from(data):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ("materials", "items", "data", "results"):
            if isinstance(data.get(key), list):
                return data[key]
    return []


def main():
    standards = request_json("GET", "/standards")
    materials_data = request_json("GET", "/materials")
    materials = items_from(materials_data)

    material_ids = list(MATERIAL_IDS)
    if not material_ids:
        material_ids = [
            material["id"]
            for material in materials
            if isinstance(material, dict) and material.get("id") is not None
        ]

    compliance_reports = {}
    for material_id in material_ids:
        compliance_reports[str(material_id)] = request_json(
            "GET", f"/materials/{material_id}/compliance"
        )

        # Apply only explicitly configured updates or property recommendations
        # returned by the compliance endpoint.
        report = compliance_reports[str(material_id)]
        updates = PROPERTY_UPDATES.get(str(material_id), {})
        if not updates and isinstance(report, dict):
            updates = report.get("recommended_properties", {})
            if not updates:
                updates = report.get("required_property_updates", {})

        if isinstance(updates, dict) and updates:
            request_json(
                "PUT",
                f"/materials/{material_id}",
                json=updates,
            )

    analysis = None
    if EQUIPMENT_IDS:
        analysis = request_json(
            "POST",
            "/analysis/start",
            json={
                "equipment_ids": EQUIPMENT_IDS,
                "material_ids": material_ids,
            },
        )

    equipment_metrics = {}
    for equipment_id in EQUIPMENT_IDS:
        equipment_metrics[str(equipment_id)] = request_json(
            "GET", f"/equipment/{equipment_id}/metrics"
        )

    # The documented API has no notification or site/resource-type endpoints.
    # Notifications cannot be enabled and site-level resource availability
    # cannot be retrieved using the available endpoints.

    print(
        {
            "standards": standards,
            "materials": materials_data,
            "compliance_reports": compliance_reports,
            "performance_analysis": analysis,
            "equipment_metrics": equipment_metrics,
            "notifications_enabled": False,
            "site_resource_types_available": False,
        }
    )


if __name__ == "__main__":
    main()

