CAMPAIGN_START = os.getenv("CAMPAIGN_START")
CAMPAIGN_END = os.getenv("CAMPAIGN_END")
UNWANTED_ITEM_IDS = {
    item_id.strip()
    for item_id in os.getenv("UNWANTED_ITEM_IDS", "").split(",")
    if item_id.strip()
}

session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})


def parse_date(value):
    if not value:
        return None
    try:
        return datetime.fromisoformat(str(value).replace("Z", "+00:00")).date()
    except (TypeError, ValueError):
        return None


# Fetch destination highlights and use them in the campaign preview.
highlights_response = session.get(
    f"{BASE_URL}/destinations/highlights",
    params={"user_id": USER_ID},
)
highlights_response.raise_for_status()
highlights = highlights_response.json()

campaign = {
    "name": "Upcoming Travel Season Destinations",
    "objective": "Showcase highlighted destinations for the upcoming travel season",
    "start_date": CAMPAIGN_START,
    "end_date": CAMPAIGN_END,
    "destinations": highlights,
}

preview_response = session.post(
    f"{BASE_URL}/simulate-preview",
    json={"campaign": campaign},
)
preview_response.raise_for_status()
preview = preview_response.json()

# Retrieve the user's itinerary and identify overlapping scheduled activities.
itinerary_response = session.get(
    f"{BASE_URL}/itinerary/view",
    params={"user_id": USER_ID},
)
itinerary_response.raise_for_status()
itinerary = itinerary_response.json()

items = itinerary if isinstance(itinerary, list) else itinerary.get(
    "items", itinerary.get("itinerary", [])
)
activities = []

for item in items:
    start = parse_date(item.get("start_date") or item.get("date"))
    end = parse_date(item.get("end_date") or item.get("date")) or start
    if start and end:
        activities.append((item, start, end))

conflicts = []
for index, (item, start, end) in enumerate(activities):
    for other, other_start, other_end in activities[index + 1:]:
        if start <= other_end and other_start <= end:
            conflicts.append(
                {
                    "item_id": item.get("id") or item.get("item_id"),
                    "conflicts_with": other.get("id") or other.get("item_id"),
                }
            )

# Cancel only items explicitly designated as unwanted.
cancelled_items = []
for item_id in UNWANTED_ITEM_IDS:
    cancel_response = session.delete(
        f"{BASE_URL}/itinerary/cancel",
        params={"user_id": USER_ID, "item_id": item_id},
    )
    cancel_response.raise_for_status()
    cancelled_items.append(item_id)

# Submit campaign details and preview results for effectiveness evaluation.
effectiveness_response = session.post(
    f"{BASE_URL}/marketing/campaign-effectiveness",
    json={
        "campaign": campaign,
        "preview": preview,
        "objectives": [
            "Showcase highlighted destinations for the upcoming travel season",
            "Evaluate campaign effectiveness and ROI before rollout",
        ],
    },
)
effectiveness_response.raise_for_status()
effectiveness = effectiveness_response.json()

