import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()


def get_json(path):
    response = session.get(f"{BASE_URL}{path}")
    response.raise_for_status()
    return response.json()


def post_json(path, payload):
    response = session.post(f"{BASE_URL}{path}", json=payload)
    response.raise_for_status()
    return response.json()


def records_from(data, keys):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in keys:
            value = data.get(key)
            if isinstance(value, list):
                return value
        for value in data.values():
            if isinstance(value, (dict, list)):
                records = records_from(value, keys)
                if records:
                    return records
    return []


def item_key(record):
    for key in ("item_id", "product_id", "sku", "id", "name"):
        if record.get(key) is not None:
            return str(record[key])
    return None


def numeric_value(record, keys):
    for key in keys:
        value = record.get(key)
        if isinstance(value, (int, float)):
            return value
    return None


inventory = get_json("/inventory/status")
purchase_patterns = get_json("/analytics/patterns")

forecast = post_json(
    "/analytics/forecast",
    {
        "historical_data": inventory,
        "purchase_patterns": purchase_patterns,
    },
)

inventory_records = records_from(
    inventory, ("items", "inventory", "products", "records", "locations")
)
forecast_records = records_from(
    forecast, ("predictions", "forecasts", "items", "products", "records")
)

stock_by_item = {}
item_details = {}
for record in inventory_records:
    if not isinstance(record, dict):
        continue
    key = item_key(record)
    quantity = numeric_value(
        record, ("quantity", "stock", "current_stock", "available_quantity")
    )
    if key is None or quantity is None:
        continue
    stock_by_item[key] = stock_by_item.get(key, 0) + quantity
    item_details.setdefault(key, record)

orders = []
for prediction in forecast_records:
    if not isinstance(prediction, dict):
        continue
    key = item_key(prediction)
    demand = numeric_value(
        prediction,
        ("predicted_demand", "forecast_demand", "forecast_quantity", "demand", "quantity"),
    )
    if key is None or demand is None:
        continue

    shortfall = max(0, demand - stock_by_item.get(key, 0))
    if shortfall > 0:
        item = {"item_id": key, "quantity": shortfall}
        for field in ("sku", "name", "product_id"):
            if field in item_details.get(key, {}):
                item[field] = item_details[key][field]
        orders.append(item)

order_result = None
if orders:
    order_result = post_json("/orders/new", {"items": orders})

supplychain_overview = get_json("/supplychain/overview")
performance_metrics = get_json("/performance/metrics")
waste_reports = get_json("/waste/reports")

