    "usability": None,     # Supply customer feedback about usability.
}

sales_data = []  # Supply historical sales quantities, in chronological order.


def api_request(method, path, **kwargs):
    response = requests.request(
        method,
        f"{BASE_URL}{path}",
        timeout=TIMEOUT,
        **kwargs,
    )
    response.raise_for_status()
    if not response.content:
        return None
    return response.json()


def find_product_id(value):
    if isinstance(value, dict):
        for key in ("product_id", "id"):
            if value.get(key) is not None:
                return value[key]
        for nested in value.values():
            found = find_product_id(nested)
            if found is not None:
                return found
    elif isinstance(value, list):
        for item in value:
            found = find_product_id(item)
            if found is not None:
                return found
    return None


def forecast_demand(quantities, periods=7):
    recent = quantities[-periods:]
    if not recent:
        return None
    return mean(recent)


def main():
    result = {"category": product_info["category"], "feedback": feedback}

    registered = api_request("POST", "/product/register", json=product_info)
    result["registration"] = registered
    product_id = find_product_id(registered)

    result["demand_forecast_from_supplied_sales_data"] = forecast_demand(sales_data)
    if result["demand_forecast_from_supplied_sales_data"] is not None:
        current_stock = product_info.get("current_stock", 0)
        result["suggested_restock_quantity"] = max(
