    # These documented analytics endpoints provide available feedback and market insights.
    result["trends"] = api_request("GET", "/analysis/trends")
    result["sentiment"] = api_request("GET", "/analysis/sentiment")
    result["aggregated_analysis"] = api_request("GET", "/analysis")
    result["products"] = api_request("GET", "/products")

    if product_id is not None:
        result["product_metrics"] = api_request(
            "GET",
            "/product/metrics",
            params={"product_id": product_id},
        )
        result["evaluation"] = api_request(
            "POST",
            f"/products/{product_id}/evaluate",
        )

    result["daily_sustainability_report"] = api_request("GET", "/report/daily")

    # The documented API has no endpoint for submitting customer feedback,
    # retrieving sales data, or executing a restock. Feedback and sales data
    # therefore need to be supplied locally; the restock quantity is only a recommendation.
    result["limitations"] = [
        "No documented endpoint submits customer feedback.",
        "No documented endpoint retrieves sales data.",
        "No documented endpoint executes a restock.",
    ]
