session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})


def get_json(path):
    response = session.get(f"{BASE_URL}{path}")
    response.raise_for_status()
    return response.json()


def as_list(data):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ("patients", "items", "inventory", "records", "data"):
            if isinstance(data.get(key), list):
                return data[key]
    return []


def item_name(item):
    if isinstance(item, str):
        return item.strip()
    if isinstance(item, dict):
        for key in ("item", "name", "supply", "medication", "product"):
            value = item.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
    return None


def item_quantity(item):
    if isinstance(item, dict):
        for key in ("quantity", "required_quantity", "count", "amount", "units"):
            value = item.get(key)
            if isinstance(value, (int, float)):
                return max(0, int(value))
    return 1


def find_requirements(value):
    requirements = []
    relevant_keys = {
        "required_supplies",
        "supplies_needed",
        "medical_supplies",
        "required_medications",
        "medications",
        "supplies",
    }

    def visit(node, in_relevant_section=False):
        if isinstance(node, dict):
            for key, child in node.items():
                relevant = in_relevant_section or key.lower() in relevant_keys
                if relevant:
                    if isinstance(child, list):
                        for entry in child:
                            name = item_name(entry)
                            if name:
                                requirements.append((name, item_quantity(entry)))
                            else:
                                visit(entry, True)
                    elif isinstance(child, dict):
                        name = item_name(child)
                        if name:
                            requirements.append((name, item_quantity(child)))
                        else:
                            visit(child, True)
                    elif isinstance(child, str):
                        requirements.append((child.strip(), 1))
                elif isinstance(child, (dict, list)):
                    visit(child, False)
        elif isinstance(node, list):
            for child in node:
                visit(child, in_relevant_section)

    visit(value)
    return requirements


patients = as_list(get_json("/patients"))
inventory = as_list(get_json("/inventory"))

patient_demand = {}
for patient in patients:
    if not isinstance(patient, dict):
