import json
import os
from datetime import datetime, timezone

import requests

BASE_URL = os.environ.get("SOCBENCH_BASE_URL", "https://api.socbench.example").rstrip("/")
API_TOKEN = os.environ.get("SOCBENCH_API_TOKEN")

session = requests.Session()
session.headers.update({"Accept": "application/json"})
if API_TOKEN:
    session.headers["Authorization"] = f"Bearer {API_TOKEN}"


def api_request(method, path, **kwargs):
    response = session.request(
        method,
        f"{BASE_URL}{path}",
        timeout=30,
        **kwargs,
    )
    response.raise_for_status()
    if response.status_code == 204 or not response.content:
        return None
    return response.json()


def records_from(payload, *keys):
    if isinstance(payload, list):
        return payload
    if isinstance(payload, dict):
        for key in keys:
            value = payload.get(key)
            if isinstance(value, list):
                return value
    return []


def collect_vulnerabilities(value):
    found = set()
    if isinstance(value, dict):
        for key, item in value.items():
            normalized_key = key.lower()
            if any(term in normalized_key for term in ("vulnerability", "cve", "software")):
                if isinstance(item, str):
                    found.add(item)
                elif isinstance(item, list):
                    for entry in item:
                        if isinstance(entry, str):
                            found.add(entry)
                        elif isinstance(entry, dict):
                            identifier = (
                                entry.get("cve_id")
                                or entry.get("cve")
                                or entry.get("id")
                                or entry.get("name")
                            )
                            if identifier:
                                found.add(str(identifier))
                elif isinstance(item, dict):
                    identifier = (
                        item.get("cve_id")
                        or item.get("cve")
                        or item.get("id")
                        or item.get("name")
                    )
                    if identifier:
                        found.add(str(identifier))
            found.update(collect_vulnerabilities(item))
    elif isinstance(value, list):
        for item in value:
            found.update(collect_vulnerabilities(item))
    return found


def rule_matches_threat(rule, threat, vulnerability_ids):
    threat_id = threat.get("id") or threat.get("threat_id")
    rule_text = json.dumps(rule, sort_keys=True).lower()
    if threat_id is not None and str(threat_id).lower() in rule_text:
        return True
    return any(vulnerability.lower() in rule_text for vulnerability in vulnerability_ids)


def main():
    hook_result = api_request(
        "POST",
        "/trigger-hook",
        json={
            "action": "enable_automatic_threat_alerts",
            "trigger": "cybersecurity_threat_detected",
        },
    )

    threats_payload = api_request("GET", "/threats")
    threats = records_from(threats_payload, "threats", "items", "data")
    alerts_payload = api_request("GET", "/alerts")
    alerts = records_from(alerts_payload, "alerts", "items", "data")

    threat_vulnerabilities = {}
    all_vulnerabilities = set()
    for threat in threats:
        threat_id = threat.get("id") or threat.get("threat_id")
        vulnerabilities = collect_vulnerabilities(threat)
        if threat_id is not None:
            threat_vulnerabilities[str(threat_id)] = sorted(vulnerabilities)
        all_vulnerabilities.update(vulnerabilities)

    updated_alerts = []
    deleted_alerts = []
    for alert in alerts:
        alert_id = alert.get("id") or alert.get("alert_id")
        if alert_id is None:
            continue

        obsolete = (
            alert.get("necessary") is False
            or alert.get("obsolete") is True
            or str(alert.get("status", "")).lower() in {"obsolete", "unnecessary", "retired"}
        )
        if obsolete:
            api_request("DELETE", f"/alerts/{alert_id}")
            deleted_alerts.append(str(alert_id))
            continue

        matched_threats = [
            threat
            for threat in threats
            if rule_matches_threat(
                alert,
                threat,
                collect_vulnerabilities(threat),
            )
        ]
        if not matched_threats:
            continue

        conditions = alert.get("conditions")
        if not isinstance(conditions, dict):
            conditions = {}

        matched_ids = [
            str(threat.get("id") or threat.get("threat_id"))
            for threat in matched_threats
            if threat.get("id") is not None or threat.get("threat_id") is not None
        ]
        matched_vulnerabilities = sorted(
            set().union(*(collect_vulnerabilities(threat) for threat in matched_threats))
        )
        conditions.update(
            {
                "threat_ids": matched_ids,
                "software_vulnerabilities": matched_vulnerabilities,
            }
        )

        update_body = {key: value for key, value in alert.items() if key not in {"id", "alert_id"}}
        update_body["conditions"] = conditions
        api_request("PUT", f"/alerts/{alert_id}", json=update_body)
        updated_alerts.append(str(alert_id))

    compliance_report = {
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "hook_triggered": hook_result is not None,
        "threat_count": len(threats),
        "threat_vulnerabilities": threat_vulnerabilities,
        "updated_alert_ids": updated_alerts,
        "deleted_alert_ids": deleted_alerts,
        "regulatory_compliance_verified": False,
        "verification_note": (
            "The documented API provides no compliance-reporting endpoint or "
            "regulatory criteria; this local report records available evidence only."
        ),
    }

    with open("compliance_report.json", "w", encoding="utf-8") as report_file:
        json.dump(compliance_report, report_file, indent=2, sort_keys=True)


if __name__ == "__main__":
    main()

