import json
import re
import requests

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30
session = requests.Session()


def get_json(path):
    response = session.get(f"{BASE_URL}{path}", timeout=TIMEOUT)
    response.raise_for_status()
    return response.json()


def put_json(path, payload):
    response = session.put(f"{BASE_URL}{path}", json=payload, timeout=TIMEOUT)
    response.raise_for_status()
    return response.json() if response.content else None


def records_from(value):
    if isinstance(value, list):
        return value
    if isinstance(value, dict):
        for key in ("items", "results", "data", "equipment", "threats", "assets"):
            candidate = value.get(key)
            if isinstance(candidate, list):
                return candidate
        return [value]
    return []


def text_of(value):
    return json.dumps(value, sort_keys=True, default=str).lower()


def tokens(value):
    return set(re.findall(r"[a-z0-9][a-z0-9._+-]{2,}", text_of(value)))


def equipment_id(equipment):
    return equipment.get("id") or equipment.get("equipment_id")


def remediation_from(threat):
    remediation_keys = {
        "patch", "patches", "software_update", "software_updates",
        "update", "updates", "remediation", "mitigation", "fix",
        "recommended_action",
    }

    found = {}

    def walk(value):
        if isinstance(value, dict):
            for key, item in value.items():
                if key.lower() in remediation_keys and item:
                    found[key] = item
                walk(item)
        elif isinstance(value, list):
            for item in value:
                walk(item)

    walk(threat)
    return found


equipment_response = get_json("/equipment")
threat_response = get_json("/threats")
equipment = records_from(equipment_response)
threats = records_from(threat_response)

analysis = []
for item in equipment:
    item_id = equipment_id(item)
    item_tokens = tokens(item)
    matched_threats = []

    for threat in threats:
        threat_tokens = tokens(threat)
        shared = item_tokens & threat_tokens
        # Exclude common words and require a concrete shared identifier or product term.
        shared -= {
            "the", "and", "for", "with", "from", "this", "that", "risk",
            "threat", "system", "equipment", "software", "security",
        }
        if shared:
            matched_threats.append(
                {
                    "threat": threat,
                    "matching_terms": sorted(shared),
                    "remediation": remediation_from(threat),
                }
            )

    analysis.append(
        {
            "equipment": item,
            "equipment_id": item_id,
            "potential_threats": matched_threats,
        }
    )

patch_results = []
for entry in analysis:
