                if not stream_response.ok:
                    findings["errors"].append(
                        f"Streaming URL returned HTTP {stream_response.status_code}."
                    )
                stream_response.close()
            except requests.RequestException as exc:
                findings["streamingAccessible"] = False
                findings["errors"].append(f"Could not access the streaming URL: {exc}")
        else:
            findings["streamingAccessible"] = False
            findings["errors"].append("The returned streaming URL is not an absolute HTTP(S) URL.")
