import json
import re
from datetime import datetime

import requests

BASE_URL = "https://api.socbench.example"
CLIENT_ID = "CLIENT_ID"
TIMEOUT = 30


def get_json(path, params=None):
    response = requests.get(
        f"{BASE_URL}{path}",
        params=params,
        timeout=TIMEOUT,
    )
    response.raise_for_status()
    return response.json()


def numeric(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def find_output_records(data):
    records = []
    output_terms = ("output", "production", "generated", "generation", "energy")

    def visit(item):
        if isinstance(item, dict):
            matching_values = [
                (key, value)
                for key, value in item.items()
                if numeric(value)
                and any(term in key.lower() for term in output_terms)
            ]
            if matching_values:
                date_value = next(
                    (
                        value
                        for key, value in item.items()
                        if any(term in key.lower() for term in ("date", "time", "timestamp"))
                        and isinstance(value, (str, int, float))
                    ),
                    None,
                )
                records.extend(
                    {"date": date_value, "metric": key, "value": value}
                    for key, value in matching_values
                )
            for value in item.values():
                visit(value)
        elif isinstance(item, list):
            for value in item:
                visit(value)

    visit(data)
    return records


def sort_key(record):
    value = record["date"]
    if value is None:
        return (1, "")
    try:
        return (0, datetime.fromisoformat(str(value).replace("Z", "+00:00")))
    except (ValueError, TypeError):
        return (0, str(value))


def summarize_output_trends(data):
    records = find_output_records(data)
    records.sort(key=sort_key)

    grouped = {}
    for record in records:
        grouped.setdefault(record["metric"], []).append(record)

    trends = {}
    for metric, points in grouped.items():
        first = points[0]
        last = points[-1]
        change = last["value"] - first["value"]
        percent_change = (
            (change / abs(first["value"])) * 100
            if first["value"] != 0
            else None
        )
        trends[metric] = {
            "points_found": len(points),
            "first": first,
            "last": last,
            "absolute_change": change,
            "percent_change": percent_change,
            "direction": "increasing" if change > 0 else "decreasing" if change < 0 else "unchanged",
        }

    return trends


def find_efficiency_metrics(data):
    metrics = {}

    def visit(item, prefix=""):
        if isinstance(item, dict):
            for key, value in item.items():
                name = f"{prefix}.{key}" if prefix else key
                if numeric(value) and any(
                    term in key.lower()
                    for term in ("efficiency", "loss", "waste", "performance")
                ):
                    metrics[name] = value
                else:
                    visit(value, name)
        elif isinstance(item, list):
            for index, value in enumerate(item):
                visit(value, f"{prefix}[{index}]")

    visit(data)
    return metrics


result = {
    "client_id": CLIENT_ID,
    "recommendations": get_json(f"/clients/{CLIENT_ID}/recommendations"),
    "energy_output_history": get_json("/energy-output/history"),
    "efficiency_metrics": get_json("/efficiency/metrics"),
}

result["energy_output_trends"] = summarize_output_trends(
