def records_in(data):
    records = []

    def visit(value):
        if isinstance(value, dict):
            records.append(value)
            for child in value.values():
                visit(child)
        elif isinstance(value, list):
            for child in value:
                visit(child)

    visit(data)
    return records

def number(value):
    try:
        return float(value)
    except (TypeError, ValueError):
